-- Batch 8 guarded price changes and seven verified pack additions.
-- Retail-estimate baseline is lowest current Kenyan supplier/retail price × 0.85; markup 30%; nearest KSh50.
begin;
do $pricing$
declare r record; affected integer;
begin
 for r in select * from (values
('gearlock-turbo-250-wp-fungicide-1kg',4399.00::numeric,3500.00::numeric),
('gradometer-480ec-termiticide-1-litre',1850.00::numeric,2450.00::numeric),
('gradometor-480ec-termiticide-100ml',399.00::numeric,400.00::numeric),
('guardian-bait-station-translucent-cover',3199.00::numeric,3300.00::numeric),
('hisense-43a6qken-4k-uhd-smart-tv-with-tv-guard-and-wall-mount-43-inch',32399.00::numeric,33150.00::numeric),
('hisense-55a6qken-4k-uhd-smart-tv-with-tv-guard-and-wall-mount-55-inch',41999.00::numeric,45600.00::numeric),
('hisense-ref205dr-double-door-fridge-with-water-dispenser-205-litres',38999.00::numeric,40150.00::numeric),
('haier-90l-single-door-direct-cool-fridge-black-90-litres',20250.00::numeric,23100.00::numeric)
 ) as v(product_id,expected_price,new_price)
 loop
  update public.products set price=r.new_price where id=r.product_id and active=true and price=r.expected_price;
  get diagnostics affected=row_count;
  if affected<>1 then raise exception 'Batch 8 guard failed for % (expected %, changed %)',r.product_id,r.expected_price,affected; end if;
 end loop;
end
$pricing$;

